edits.find:
toast[type](finalMessage, {
  duration,
  action: undoable
    ? {
        label: translate("ra.action.undo"),
        onClick: handleUndo,
      }
    : undefined,
  onDismiss: handleExited,
  onAutoClose: handleExited,
});

edits.replace:
window.setTimeout(() => {
  toast[type](finalMessage, {
    duration,
    action: undoable
      ? {
          label: translate("ra.action.undo"),
          onClick: handleUndo,
        }
      : undefined,
    onDismiss: handleExited,
    onAutoClose: handleExited,
  });
}, 200);
